def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_def = sum(1 for x in op if x == 'D')
    my_def = sum(1 for x in my if x == 'D')

    if n >= 100:
        return 'D'

    # pure cooperator: exploit at the very end
    if op_def == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # pure defector
    if op_def == n:
        return 'D'

    last_m, last_o = history[-1]

    # recent-window stats
    w = op[-6:] if n >= 6 else op
    wd = sum(1 for x in w if x == 'D')
    wl = len(w)

    # strong continued defection: keep punishing
    if n >= 4 and op[-4:].count('D') >= 4:
        return 'D'

    # detect TFT-like: opponent mirrors our previous move
    if n >= 3:
        matches = 0
        for i in range(1, n):
            if op[i] == my[i - 1]:
                matches += 1
        if matches >= n - 1:
            # opponent is (near) TFT: cooperate unless they just defected
            if last_o == 'D':
                return 'D'
            return 'C'

    # recovery from mutual defection spirals
    if last_o == 'D' and last_m == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if my[i] == 'D' and op[i] == 'D':
                run += 1
            else:
                break
        if run == 1 and op_def * 3 < n:
            return 'C'
        if run >= 3 and op_def * 2 < n:
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # opponent just cooperated
    if last_o == 'C':
        if last_m == 'D':
            # apologize: return to cooperation unless they retaliate often
            return 'C'
        # sustained cooperation check
        if wd == 0:
            # greedy: occasionally exploit a very cooperative opponent late
            if n >= 80 and op_def <= 2 and n % 7 == 0:
                return 'D'
            return 'C'
        if wd <= 1:
            if n >= 95 and op_def * 4 < n:
                if n % 3 == 0:
                    return 'D'
            return 'C'
        if wd >= 3:
            return 'D'
        # moderate: cooperate
        return 'C'

    # opponent just defected (but we cooperated)
    if last_o == 'D':
        # isolated defection: retaliate once then resume
        if wd <= 1:
            return 'D'
        # opponent mixes: tit-for-tat
        return 'D'
    return 'C'
